param([string]$FixtureRoot=(Join-Path ([IO.Path]::GetTempPath()) 'qbit-context-shared-workstream'))
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$run=Join-Path $FixtureRoot ([guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $run|Out-Null
$install=Join-Path $PSScriptRoot '../../install.ps1';$hostExe=(Get-Command powershell.exe).Source;$passed=0
function WriteUtf8($path,$value){New-Item -ItemType Directory -Force (Split-Path $path -Parent)|Out-Null;[IO.File]::WriteAllText($path,$value,[Text.UTF8Encoding]::new($false))}
function Git($path,[string[]]$arguments){$old=$ErrorActionPreference;$ErrorActionPreference='Continue';try{$out=@(&git.exe -c core.longpaths=true -C $path @arguments 2>&1);$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old};if($code){throw "Fixture Git failed: $($arguments[0])"};return ($out -join "`n").Trim()}
function Run($script,[string[]]$arguments){$old=$ErrorActionPreference;$ErrorActionPreference='Continue';try{$out=@(&$hostExe -NoProfile -ExecutionPolicy Bypass -File $script @arguments 2>&1);$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old};Add-Content (Join-Path $run 'commands.log') ($script+' '+($arguments -join ' ')+"`nexit=$code`n"+($out -join "`n"));return [pscustomobject]@{Code=$code;Text=($out -join "`n")}}
function Assert($condition,$message){if(-not $condition){throw $message}}
function Case($name,[scriptblock]$body){&$body;$script:passed++;Write-Output "PASS $name"}
function Repo($path){New-Item -ItemType Directory -Force $path|Out-Null;Git $path @('init','-q','-b','main')|Out-Null;Git $path @('config','user.name','Fixture')|Out-Null;Git $path @('config','user.email','fixture@example.invalid')|Out-Null;WriteUtf8 (Join-Path $path 'source.txt') 'source';Git $path @('add','source.txt')|Out-Null;Git $path @('commit','-q','-m','init')|Out-Null}
function Payload($root,$repo,$id='shared-stream',$terminal=$false){$next=if($terminal){'Retain completed history.'}else{'Finish ITEM-1.'};$status=if($terminal){'COMPLETED'}else{'IN_PROGRESS'};$ws=@{id=$id;title='Shared identity preservation';objective='Preserve global workstream identity';status=$status;repositories=@(@{repository=$repo;role='owner'});cursor=@{currentItemId=$(if($terminal){$null}else{'ITEM-1'});lastCompletedItemId=$null;lastCompletedAction=$null;phase='validation';nextAction=$next};items=@(@{id='ITEM-1';title='Original item';status=$status;priority='HIGH';scope=@('context');acceptanceCriteria=@('Preserved');dependsOn=@();blockedBy=@();validationRequirements=@('test');notes=@()})};$cp=@{schemaVersion=2;repository=$repo;scope='global-workstream';status=$(if($terminal){'VALIDATED'}else{'IN_PROGRESS'});objective='Preserve global identity.';confirmedFindings=@();decisions=@();rejectedApproaches=@();validation=@();openQuestions=@();nextAction=$next;continuity=@{mode='tracked';workstream=$ws;validationLedger=@()}};WriteUtf8 (Join-Path $root '.ai-bridge/context-checkpoint.json') ($cp|ConvertTo-Json -Depth 20)}
function Cache($root){Join-Path $root '.ai/context/cache/project-context'}
function Launch($root,$action){Run (Join-Path $root '.ai/context/context.ps1') @($action)}
$exit=0
try{
 $bare=Join-Path $run 'context.git';New-Item -ItemType Directory -Force $bare|Out-Null;Git $bare @('init','--bare','-q','--initial-branch=main')|Out-Null
 $central=Join-Path $run 'central';Repo $central
 $r=Run $install @('-Operation','install','-Mode','central','-Target',$central,'-ProjectId','demo','-RepositoryId','demo-context','-ContextRemote',$bare);Assert ($r.Code -eq 0) $r.Text
 WriteUtf8 (Join-Path $central 'repositories/repositories.yaml') "project: demo`nrepositories:`n  member-a:`n    role: test-owner`n  member-b:`n    role: test-owner`n"
 Git $central @('add','--all')|Out-Null;Git $central @('commit','-q','-m','central')|Out-Null;Git $central @('remote','add','origin',$bare)|Out-Null;Git $central @('push','-q','-u','origin','main')|Out-Null
 $a=Join-Path $run 'a';$b=Join-Path $run 'b';foreach($member in @(@{root=$a;id='member-a'},@{root=$b;id='member-b'})){Repo $member.root;$r=Run $install @('-Operation','install','-Mode','member','-Target',$member.root,'-ProjectId','demo','-RepositoryId',$member.id,'-ContextRemote',$bare);Assert ($r.Code -eq 0) $r.Text;$r=Launch $member.root 'start';Assert ($r.Code -eq 0) $r.Text;Git (Cache $member.root) @('config','user.name','Fixture')|Out-Null;Git (Cache $member.root) @('config','user.email','fixture@example.invalid')|Out-Null}
 Case 'owning member creates tracked stream' {Payload $a 'member-a';$r=Launch $a 'checkpoint';Assert ($r.Code -eq 0) $r.Text}
 Case 'fresh registered member cannot overwrite another active stream' {Payload $b 'member-b';$before=Git $bare @('rev-parse','refs/heads/main');$r=Launch $b 'checkpoint';Assert ($r.Code -ne 0) 'Another member silently overwrote global active Workstream';Assert ((Git $bare @('rev-parse','refs/heads/main')) -eq $before) 'Rejected collision published changes';Assert ((Git (Cache $b) @('status','--porcelain')) -eq '') 'Rejected collision dirtied cache'}
 Case 'owner explicitly archives stream' {Payload $a 'member-a' 'shared-stream' $true;$r=Launch $a 'checkpoint';Assert ($r.Code -eq 0) $r.Text;$script:archiveHash=(Get-FileHash (Join-Path (Cache $a) 'workstreams/archive/shared-stream.json')).Hash}
 Case 'fresh member cannot reopen globally archived ID' {Payload $b 'member-b';$before=Git $bare @('rev-parse','refs/heads/main');$r=Launch $b 'checkpoint';Assert ($r.Code -ne 0) 'Another member reopened archived Workstream';Assert ((Git $bare @('rev-parse','refs/heads/main')) -eq $before) 'Archived collision advanced remote'}
 Case 'owner can start distinct stream preserving archive' {Payload $a 'member-a' 'next-stream';$r=Launch $a 'checkpoint';Assert ($r.Code -eq 0) $r.Text;Assert ((Get-FileHash (Join-Path (Cache $a) 'workstreams/archive/shared-stream.json')).Hash -eq $archiveHash) 'Archive was erased'}
 Case 'forgotten archived identity cannot be reused after cursor moves' {Payload $b 'member-b' 'unique-b';$r=Launch $b 'checkpoint';Assert ($r.Code -eq 0) $r.Text;Payload $b 'member-b' 'unique-b' $true;$r=Launch $b 'checkpoint';Assert ($r.Code -eq 0) $r.Text;Payload $b 'member-b' 'shared-stream';$before=Git $bare @('rev-parse','refs/heads/main');$r=Launch $b 'checkpoint';Assert ($r.Code -ne 0) 'Prior cursor let archived ID be overwritten';Assert ((Git $bare @('rev-parse','refs/heads/main')) -eq $before) 'Prior archive changed'}
 Case 'owner cannot reopen own old archive after a snapshot' {Payload $a 'member-a' 'next-stream' $true;$r=Launch $a 'checkpoint';Assert ($r.Code -eq 0) $r.Text;$file=Join-Path $a '.ai-bridge/context-checkpoint.json';Payload $a 'member-a' 'next-stream' $true;$cp=Get-Content -Encoding UTF8 $file -Raw|ConvertFrom-Json;$cp.continuity.mode='snapshot';$cp.continuity.workstream=$null;WriteUtf8 $file ($cp|ConvertTo-Json -Depth 20);$r=Launch $a 'checkpoint';Assert ($r.Code -eq 0) $r.Text;Payload $a 'member-a';$before=Git $bare @('rev-parse','refs/heads/main');$r=Launch $a 'checkpoint';Assert ($r.Code -ne 0) 'Owner reopened archive after snapshot';Assert ((Git $bare @('rev-parse','refs/heads/main')) -eq $before) 'Reopen advanced remote';Assert ((Get-FileHash (Join-Path (Cache $a) 'workstreams/archive/shared-stream.json')).Hash -eq $archiveHash) 'Own old archive changed'}
}catch{$exit=1;Write-Output ('FAIL '+$_.Exception.Message)}finally{[pscustomobject]@{passed=$passed;failed=$exit;skipped=0;exitCode=$exit;fixture=$run}|ConvertTo-Json|Set-Content (Join-Path $run 'results.json');Write-Output "RESULT passed=$passed failed=$exit skipped=0 evidence=$run"}
exit $exit
